arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1981_04.json', 'r') as f:
    data = json.load(f)

# Print keys at top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(d, list) and len(d) < 20 and indent < 2:
        for i, item in enumerate(d[:3]):
            print(' ' * indent + f'[{i}]')
            print_structure(item, indent + 2)

print_structure(data)
"
